mapper.select:
select A.SEQ_NO, A.BOOKSET_ID as booksetId, /** 账套代码 **/ bok.BOOKSET_NAME as booksetName,/**账套名称**/ B.BUSI_ID as bokDetailId,/**账务明细代码**/ C.FINPROD_ABBR as finProdAbbr, /**金融产品简称**/ C.CAPI_INCOME_FEATURE as profitType, /**本金收益特征**/ E.TYPE_3 as finType, /**分类3 (税务分类) **/ A.TAX_P_TYPE as taxPType, /**确认标识**/ A.VAT_TYPE as vatType, /**增值税类型**/ A.HAPPEN_AMT as happenAmt, /**发生含税销售额**/ A.CALC_TYPE as calcType , /**计税方式**/ A.BAL_AMT as balAmt, /**计税余额发生额**/ ( CASE WHEN A.TAX_RATE is null then 0.00 ELSE A.TAX_RATE*100 END )as taxRate, /**税率 - 应税税率（%） **/ A.HAPPEN_DATE as happenDate, /**发生日期**/ ( CASE WHEN A.TAX_RATE is not null THEN (A.HAPPEN_AMT)/(1+A.TAX_RATE) ELSE A.HAPPEN_AMT END ) as sellAmt /**销售额**/ from TAX_BOK_DETAIL A inner join BOK_DETAIL_ID B on A.BOK_DETAIL_ID=B.BOK_DETAIL_ID left join FIN_PRODUCT C on B.BUSI_ID =C.FINPROD_ID and B.BUSI_DETAIL_TYPE=C.FINPROD_TYPE left join FIN_TRADE_PRODUCT D on B.BUSI_ID = D.FINPROD_ID and B.BUSI_DETAIL_TYPE =D.FINPROD_TYPE left join FIN_PRODUCT_TYPE E on B.BUSI_ID = E.FINPROD_ID left join BOK_BOOKSET bok on A.BOOKSET_ID = bok.BOOKSET_ID where 1=1
AND A.BOOKSET_ID in
#{item}
AND B.BUSI_ID LIKE '%' || #{bokDetailId} || '%'
AND E.TYPE_3 in
#{item}
AND A.HAPPEN_DATE >= #{happenDateBegin}
AND A.HAPPEN_DATE <= #{happenDateEnd}
AND A.VAT_TYPE in
#{item}
AND A.CALC_TYPE in
#{item}
AND A.TAX_P_TYPE in
#{item}
GROUP BY A.SEQ_NO, A.BOOKSET_ID , B.BUSI_ID , C.FINPROD_ABBR, C.CAPI_INCOME_FEATURE , E.TYPE_3 , A.TAX_P_TYPE, A.VAT_TYPE, A.HAPPEN_AMT , A.CALC_TYPE , A.BAL_AMT , A.TAX_RATE , A.HAPPEN_DATE, bok.BOOKSET_NAME ORDER BY A.BOOKSET_ID DESC, B.BUSI_ID desc
